//! The Atari ST system fonts (EmuTOS `fnt_st_6x6`/`fnt_st_8x8`/`fnt_st_8x16`).
//!
//! Glyph bitmaps are generated by `cargo xtask gen-font` into
//! [`font_data`](super::font_data) (one byte-array per character,
//! `form_height` rows, MSB = leftmost pixel). The metrics below are the
//! EmuTOS font-header (`Fonthead`) values.
//!
//! Two layers live here:
//!
//! * The [`SysFont`] ring ([`FON_6X6`]/[`FON_8X8`]/[`FON_8X16`], EmuTOS
//!   `font_ring[]` / `vdi_text.c:604`) that `vst_height`/`vst_point` select
//!   among and that `v_gtext` renders with, plus the two screen-height rules
//!   that pick the default face from it: [`text_init_def_font`] (the VDI's and
//!   so the AES's) and [`font_set_default`] (the VT52 console's). Under 400
//!   lines both are the 8×8 face, from 400 lines up the 8×16 face (V32).
//! * The `pub const` metrics + [`glyph`] of the **8×16 face** alone
//!   (`fnt_st_8x16`). They are that face's numbers, not "the" system font:
//!   code that draws in the default font asks [`text_init_def_font`] /
//!   [`font_set_default`] for the face and reads [`glyph_rows`].

pub use super::font_data::{SYSTEM_FONT_6X6, SYSTEM_FONT_8X16, SYSTEM_FONT_8X8};

/// Character cell width of the 8×16 face in pixels (monospace).
pub const CELL_W: i16 = 8;
/// Character cell height of the 8×16 face in pixels — **not** the default
/// font's on every screen (8 under 400 lines, [`text_init_def_font`]).
pub const CELL_H: i16 = 16;
/// Baseline distance from the top of the cell (`top`).
pub const TOP: i16 = 13;
/// Half-line distance from the baseline (`half`).
pub const HALF: i16 = 8;
/// Ascent (cap-top) distance from the baseline.
pub const ASCENT: i16 = 11;
/// Descent distance below the baseline.
pub const DESCENT: i16 = 2;

// Remaining `Fonthead` metrics for `fnt_st_8x16` (EmuTOS
// `bios/fnt_st_8x16.c`), reported by the text inquiry/attribute opcodes.
/// Font face id (`font_id`).
pub const FONT_ID: i16 = 1;
/// Nominal point size (`point`).
pub const POINT: i16 = 10;
/// First character code present (`first_ade`).
pub const FIRST_ADE: i16 = 0;
/// Last character code present (`last_ade`).
pub const LAST_ADE: i16 = 255;
/// Maximum glyph width in pixels (`max_char_width`).
pub const MAX_CHAR_WIDTH: i16 = 7;
/// Bold (thicken) horizontal overstrike in pixels (`thicken`).
pub const THICKEN: i16 = 1;
/// Underline thickness in pixels (`ul_size`).
pub const UL_SIZE: i16 = 1;
/// Lighten (greying) AND-mask applied per glyph row (`lighten`).
pub const LIGHTEN: u8 = 0x55;
/// Skew (italic) shift mask, one bit per scanline (`skew`).
pub const SKEW: u16 = 0x5555;
/// Left offset of the glyph within the cell (`left_offset`).
pub const LEFT_OFFSET: i16 = 1;
/// Right offset of the glyph within the cell (`right_offset`).
pub const RIGHT_OFFSET: i16 = 7;
/// Distance from the baseline to the cell bottom (`bottom`).
pub const BOTTOM: i16 = 2;
/// Name string (`name`), reported by `vqt_name`.
pub const NAME: &[u8] = b"8x16 system font";
/// `vqt_name` font-name field length in WORDs (GEM `Fonthead.name`).
pub const NAME_LEN: usize = 32;

/// The 16-row bitmap for character `c` (low 8 bits select the glyph) in the
/// 8×16 face. For the default font of a screen use [`glyph_rows`].
#[inline]
pub fn glyph(c: u16) -> &'static [u8; 16] {
    &SYSTEM_FONT_8X16[(c & 0xFF) as usize]
}

// ── the AES's second desktop font size ("SMALL") ─────────────────────
//
// EmuTOS `gsx_start` (gemgraf.c:405-410) keeps **two** cell sizes for the
// AES to draw with:
//
//   gsx_textsize(&gl_wptschar, &gl_hptschar, &gl_wchar, &gl_hchar);
//   gl_ws.ws_chmaxh = gl_hptschar;            /* the IBM (normal) font */
//   vst_height(gl_ws.ws_chminh, &gl_wsptschar, &gl_hsptschar,
//              &gl_wschar, &gl_hschar);       /* the SMALL font       */
//
// `ws_chminh` is `SIZ_TAB[1]` from `v_opnwk` — the smallest `top` across
// the system face (`vdi_text.c:635-636`), which for the ring below is the
// 6×6 face's `top = 4` (our [`super::workstation::siz_tab`] folds the same
// ring and reports the same 4). `vst_height(4)` then selects the 6×6 face
// (`vdi_text.c:706-713`: the largest font whose `top <= 4`) and returns
// `cell_width = max_cell_width = 6`, `cell_height = top + bottom + 1 = 6`
// (`setup_width_height`, `vdi_text.c:666-679`).
//
// `SIZ_TAB[1]` folds the whole ring and so does not depend on the screen:
// on every screen the AES's SMALL font is the 6×6 face, and the two
// constants below are `gl_wschar`/`gl_hschar`. (The normal font,
// `gl_wchar`/`gl_hchar`, is the screen's [`text_init_def_font`].) The unit test at the
// bottom of this module re-derives both from [`RING`] so they cannot drift.

/// The AES SMALL-font cell width — EmuTOS `gl_wschar` (`gemgraf.c:42`).
/// Used by `gr_gicon` for an icon's overlay character and its label, and
/// by any `TEDINFO` whose `te_font` is `SMALL`.
pub const SMALL_CELL_W: i16 = 6;
/// The AES SMALL-font cell height — EmuTOS `gl_hschar` (`gemgraf.c:43`).
pub const SMALL_CELL_H: i16 = 6;

/// The 6-row bitmap for character `c` (low 8 bits select the glyph) in the
/// AES SMALL font. The 6 pixels are packed into bits 7..2 of each row, the
/// layout [`super::backend::RasterBackend::draw_glyph_sized`] expects for a
/// `cell_w` of 6.
#[inline]
pub fn glyph_small(c: u16) -> &'static [u8; 6] {
    &SYSTEM_FONT_6X6[(c & 0xFF) as usize]
}

/// One of the three built-in system-font sizes. The discriminant is the
/// ring index (EmuTOS `font_ring[0..2]`, smallest first).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SysFontId {
    /// 6×6 system font (`fnt_st_6x6`).
    F6x6 = 0,
    /// 8×8 system font (`fnt_st_8x8`).
    F8x8 = 1,
    /// 8×16 system font (`fnt_st_8x16`).
    F8x16 = 2,
}

/// A built-in monospace system font: the EmuTOS `Fonthead` metrics that
/// the text path (`v_gtext`, `vst_height`/`vst_point`) consumes, plus the
/// [`SysFontId`] used to fetch its glyph rows. Only the fields the text
/// path needs are carried (all three fonts have `font_id = 1`, standard
/// mono format, first/last ade 0/255).
///
/// `Copy` so the scaled scratch header EmuTOS keeps in `vwk->scratch_head`
/// (`vdi_text.c:770-817`) can be produced by value on demand.
#[derive(Clone, Copy)]
pub struct SysFont {
    /// Which raster this font's glyphs come from.
    pub id: SysFontId,
    /// Face id (`font_id`) — 1 for all three system fonts.
    pub font_id: i16,
    /// Nominal point size (`point`), used by `vst_point` selection.
    pub point: i16,
    /// First character code present (`first_ade`).
    pub first_ade: i16,
    /// Last character code present (`last_ade`).
    pub last_ade: i16,
    /// Baseline distance from the cell top (`top`), used by `vst_height`.
    pub top: i16,
    /// Ascent (cap-top) distance from the baseline (`ascent`).
    pub ascent: i16,
    /// Half-line distance from the baseline (`half`).
    pub half: i16,
    /// Descent distance below the baseline (`descent`).
    pub descent: i16,
    /// Distance from the baseline to the cell bottom (`bottom`).
    pub bottom: i16,
    /// Maximum glyph width (`max_char_width`).
    pub max_char_width: i16,
    /// Cell advance width (`max_cell_width`).
    pub max_cell_width: i16,
    /// Glyph left offset within the cell (`left_offset`).
    pub left_offset: i16,
    /// Glyph right offset within the cell (`right_offset`).
    pub right_offset: i16,
    /// Bold overstrike in pixels (`thicken`).
    pub thicken: i16,
    /// Underline thickness in pixels (`ul_size`).
    pub ul_size: i16,
    /// Lighten (greying) AND-mask (`lighten`).
    pub lighten: u16,
    /// Skew (italic) shift mask (`skew`).
    pub skew: u16,
    /// Number of scanlines per glyph (`form_height`) = cell height.
    pub form_height: i16,
    /// Face name (`name`), NUL-free.
    pub name: &'static [u8],
    /// `flags & F_DEFAULT` (`include/fonthdr.h:21`) — a face [`text_init_def_font`]
    /// may choose as the default. Set on the 8×8 and the 8×16 face
    /// (`bios/fnt_st_8x8.c:165`, `bios/fnt_st_8x16.c:293`), not on the 6×6
    /// (`bios/fnt_st_6x6.c:109`).
    pub f_default: bool,
}

/// 6×6 system font header (EmuTOS `bios/fnt_st_6x6.c`).
pub static FON_6X6: SysFont = SysFont {
    id: SysFontId::F6x6,
    font_id: 1,
    point: 8,
    first_ade: 0,
    last_ade: 255,
    top: 4,
    ascent: 4,
    half: 3,
    descent: 1,
    bottom: 1,
    max_char_width: 5,
    max_cell_width: 6,
    left_offset: 0,
    right_offset: 3,
    thicken: 1,
    ul_size: 1,
    lighten: 0x5555,
    skew: 0xAAAA,
    form_height: 6,
    name: b"6x6 system font",
    f_default: false,
};

/// 8×8 system font header (EmuTOS `bios/fnt_st_8x8.c`).
pub static FON_8X8: SysFont = SysFont {
    id: SysFontId::F8x8,
    font_id: 1,
    point: 9,
    first_ade: 0,
    last_ade: 255,
    top: 6,
    ascent: 6,
    half: 4,
    descent: 1,
    bottom: 1,
    max_char_width: 7,
    max_cell_width: 8,
    left_offset: 1,
    right_offset: 3,
    thicken: 1,
    ul_size: 1,
    lighten: 0x5555,
    skew: 0x5555,
    form_height: 8,
    name: b"8x8 system font",
    f_default: true,
};

/// 8×16 system font header (EmuTOS `bios/fnt_st_8x16.c`).
pub static FON_8X16: SysFont = SysFont {
    id: SysFontId::F8x16,
    font_id: 1,
    point: 10,
    first_ade: 0,
    last_ade: 255,
    top: 13,
    ascent: 11,
    half: 8,
    descent: 2,
    bottom: 2,
    max_char_width: 7,
    max_cell_width: 8,
    left_offset: 1,
    right_offset: 7,
    thicken: 1,
    ul_size: 1,
    lighten: 0x5555,
    skew: 0x5555,
    form_height: 16,
    name: b"8x16 system font",
    f_default: true,
};

/// The font ring, smallest first (EmuTOS `font_ring[0..2]`, all `font_id
/// = 1`). `vst_height`/`vst_point` walk this to pick a size.
pub const RING: [SysFontId; 3] = [SysFontId::F6x6, SysFontId::F8x8, SysFontId::F8x16];

/// EmuTOS `text_init`'s choice of `def_font` (`vdi/vdi_text.c:604-623`), the
/// face every workstation opens with (`text_init2`, `:574`) and so the one the
/// AES takes `gl_wchar`/`gl_hchar` from (`gsx_start`, `aes/gemgraf.c:405`):
///
/// ```c
/// cell_height = (V_REZ_VT >= 400) ? 16 : 8;   /* to select among default fonts */
/// ...
/// if (fnt_ptr->flags & F_DEFAULT) {
///     if (!def_font)
///         def_font = fnt_ptr;
///     else if (def_font->form_height != cell_height)
///         def_font = fnt_ptr;
/// }
/// ```
///
/// over every font of the ring in order. For the built-in ring that is the
/// 8×8 face under 400 lines and the 8×16 face from 400 up. EmuTOS runs the
/// walk once per `v_opnwk`; NewTOS' screen height does not change after
/// boot, so the callers evaluate it for the live `V_REZ_VT`.
///
/// Every ring has an `F_DEFAULT` face; the `None` arm of the walk (EmuTOS
/// would leave `def_font` NULL) cannot occur, so the first ring face stands in
/// for it, which is also what EmuTOS' face lookups fall back to (`&fon6x6`,
/// `vdi_text.c:964`).
pub fn text_init_def_font(v_rez_vt: i16) -> SysFontId {
    let cell_height = if v_rez_vt >= 400 { 16 } else { 8 };
    let mut def: Option<SysFontId> = None;
    for &id in &RING {
        if !font(id).f_default {
            continue;
        }
        match def {
            None => def = Some(id),
            Some(d) if font(d).form_height != cell_height => def = Some(id),
            Some(_) => {}
        }
    }
    def.unwrap_or(RING[0])
}

/// EmuTOS `font_set_default`'s font for the VT52 console (`bios/font.c:72-88`):
/// `font = (V_REZ_VT < 400) ? &fon8x8 : &fon8x16;` — the cell `v_cel_ht`,
/// `v_cel_mx`/`v_cel_my` and every glyph the console draws come from it.
pub fn font_set_default(v_rez_vt: i16) -> SysFontId {
    if v_rez_vt < 400 {
        SysFontId::F8x8
    } else {
        SysFontId::F8x16
    }
}

/// The [`SysFont`] header for a ring id.
#[inline]
pub fn font(id: SysFontId) -> &'static SysFont {
    match id {
        SysFontId::F6x6 => &FON_6X6,
        SysFontId::F8x8 => &FON_8X8,
        SysFontId::F8x16 => &FON_8X16,
    }
}

/// Map a raw text character code to font `f`'s glyph index, substituting
/// `'?'` for any code outside `[first_ade, last_ade]` (EmuTOS
/// `output_text`, `vdi_text.c:464`: `if (temp < first_ade || temp >
/// last_ade) temp = '?'`), then applying the `first_ade` offset. The
/// caller passes the raw signed `INTIN` word, so a negative code (`< 0 =
/// first_ade`) or a code above `last_ade` both become `'?'` rather than a
/// wrapped glyph.
#[inline]
pub fn map_code(f: &SysFont, code: i16) -> u16 {
    let c = if code < f.first_ade || code > f.last_ade {
        b'?' as i16
    } else {
        code
    };
    (c - f.first_ade) as u16
}

/// The `form_height` rows of character `c` (low 8 bits) in font `id`, MSB =
/// leftmost pixel (the 6×6 face uses bits 7..2) — the slice
/// [`RasterBackend::draw_glyph_sized`](super::backend::RasterBackend::draw_glyph_sized)
/// takes with the face's `max_cell_width` × `form_height`.
#[inline]
pub fn glyph_rows(id: SysFontId, c: u16) -> &'static [u8] {
    let c = (c & 0xFF) as usize;
    match id {
        SysFontId::F6x6 => &SYSTEM_FONT_6X6[c],
        SysFontId::F8x8 => &SYSTEM_FONT_8X8[c],
        SysFontId::F8x16 => &SYSTEM_FONT_8X16[c],
    }
}

/// One glyph scanline (`row`, 0-based from the cell top) of character `c`
/// (low 8 bits) in font `id`. Bit 7 of the returned byte is the leftmost
/// pixel; the 6×6 font uses bits 7..2. `row` must be `< form_height`.
#[inline]
pub fn glyph_row(id: SysFontId, c: u16, row: usize) -> u8 {
    let c = (c & 0xFF) as usize;
    match id {
        SysFontId::F6x6 => SYSTEM_FONT_6X6[c][row],
        SysFontId::F8x8 => SYSTEM_FONT_8X8[c][row],
        SysFontId::F8x16 => SYSTEM_FONT_8X16[c][row],
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `SMALL_CELL_W`/`SMALL_CELL_H` must be exactly what EmuTOS's
    /// `gsx_start` would get back from `vst_height(SIZ_TAB[1])`: fold the
    /// ring for the minimum `top` (EmuTOS `text_init`, `vdi_text.c:635`),
    /// run `vst_height`'s "largest font whose `top <= height`" selection
    /// (`vdi_text.c:706-713`), then read `setup_width_height`'s outputs
    /// (`max_cell_width`, `top + bottom + 1`).
    #[test]
    fn small_font_is_what_vst_height_of_siz_tab_1_selects() {
        let min_top = RING
            .iter()
            .map(|&id| font(id))
            .filter(|f| f.font_id == FONT_ID)
            .map(|f| f.top)
            .min()
            .unwrap();
        assert_eq!(min_top, 4, "SIZ_TAB[1] (ws_chminh)");

        // vst_height(min_top): walk the ring, keep the last face whose
        // `top <= min_top`.
        let mut sel = font(RING[0]);
        for &id in &RING {
            let f = font(id);
            if f.font_id == FONT_ID && f.top <= min_top {
                sel = f;
            }
        }
        assert_eq!(sel.top, min_top, "an exact size match, so no DDA scaling");
        assert_eq!(SMALL_CELL_W, sel.max_cell_width);
        assert_eq!(SMALL_CELL_H, sel.top + sel.bottom + 1);
        assert_eq!(sel.form_height, SMALL_CELL_H, "glyph rows == cell height");
    }

    /// `text_init`'s walk (`vdi_text.c:612-623`) over the ring: the 8×8 face
    /// under 400 lines, the 8×16 face from 400 up — and `CELL_W`/`CELL_H` are
    /// the 8×16 face's cell, `top + bottom + 1` as `vqt_attributes` reports it.
    #[test]
    fn def_font_follows_v_rez_vt() {
        for h in [0, 200, 240, 399] {
            assert_eq!(text_init_def_font(h), SysFontId::F8x8, "V_REZ_VT {h}");
            assert_eq!(font_set_default(h), SysFontId::F8x8, "console, V_REZ_VT {h}");
        }
        for h in [400, 480, 1080] {
            assert_eq!(text_init_def_font(h), SysFontId::F8x16, "V_REZ_VT {h}");
            assert_eq!(font_set_default(h), SysFontId::F8x16, "console, V_REZ_VT {h}");
        }
        let f = font(SysFontId::F8x16);
        assert_eq!(CELL_W, f.max_cell_width);
        assert_eq!(CELL_H, f.top + f.bottom + 1);
        assert_eq!(f.form_height, CELL_H);
        for id in RING {
            assert_eq!(glyph_rows(id, b'A' as u16).len(), font(id).form_height as usize);
        }
    }
}
